parameters.jsCode:
// Bouwt het casusdossier op uit de rijen van Buddy Data en zet het oorspronkelijke
// chatbericht (incl. bijlagen) er weer bij, zodat de rest van de flow ongewijzigd doorloopt.
//
// Kolommen in tabel `fc_advies` hebben een fc_-prefix. De helper leest beide varianten,
// zodat dit blijft werken als de kolomnamen ooit veranderen.
const triggerItem = $('When chat message received').first();
const trigger = triggerItem.json ?? {};

const MAX_DOSSIER = 60000;   // ruwweg 15k tokens; oudste rondes vallen als eerste af

const veld = (r, naam) => r['fc_' + naam] ?? r[naam] ?? '';

const rijen = $input.all()
  .map(i => i.json ?? {})
  // lege rij bij een nog leeg dossier eruit (alwaysOutputData)
  .filter(r => r && (veld(r, 'session_id') || veld(r, 'inhoud') || veld(r, 'ronde')))
  .sort((a, b) => {
    const ta = String(a.created_at ?? ''), tb = String(b.created_at ?? '');
    if (ta && tb) return ta.localeCompare(tb);
    return Number(veld(a, 'ronde') || 0) - Number(veld(b, 'ronde') || 0);   // terugval
  });

const blokken = rijen.map(r => {
  const moment = String(r.created_at ?? '').slice(0, 16) || 'moment onbekend';
  return `### Ronde ${veld(r, 'ronde') || '?'} (${moment}) - geraadpleegd: ${veld(r, 'specialisten') || 'geen'}\n${veld(r, 'inhoud')}`;
});

// Nieuwste rondes eerst behouden bij afkappen.
let dossier = '';
for (let i = blokken.length - 1; i >= 0; i--) {
  if (dossier.length + blokken[i].length > MAX_DOSSIER) {
    dossier = '[...oudere rondes weggelaten wegens omvang...]\n\n' + dossier;
    break;
  }
  dossier = blokken[i] + (dossier ? '\n\n' + dossier : '');
}

return [{
  json: { ...trigger, dossier, dossierRondes: rijen.length, volgendeRonde: rijen.length + 1 },
  binary: triggerItem.binary ?? {},
}];

// Een item per bijgevoegd bestand. De binary-sleutel wordt genormaliseerd naar 'data'
// zodat de nodes erna altijd dezelfde property kunnen gebruiken.
const out = [];
for (const item of $input.all()) {
  for (const [key, meta] of Object.entries(item.binary ?? {})) {
    const naam = meta.fileName || key;
    out.push({
      json: { bestandsnaam: naam, ext: (naam.split('.').pop() || '').toLowerCase() },
      binary: { data: meta },
      pairedItem: { item: item.index ?? 0 },
    });
  }
}
if (out.length === 0) throw new Error('Geen bestanden gevonden in het chatbericht.');
return out;

// ===== Code node: "Document naar tekst" (docx, txt, csv, md, html, json) =====
// Alleen ingebouwde Node-modules (zlib). Geen npm-packages, geen env-vars nodig.
// Mode: Run Once for All Items
const zlib = require('zlib');

const MAX_CHARS_PER_DOC = 40000;

function zipRead(buf, wantedName) {
  let eocd = -1;
  const floor = Math.max(0, buf.length - 65558);
  for (let i = buf.length - 22; i >= floor; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error('geen geldig docx/zip-bestand');
  const count = buf.readUInt16LE(eocd + 10);
  let off = buf.readUInt32LE(eocd + 16);
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(off) !== 0x02014b50) break;
    const method   = buf.readUInt16LE(off + 10);
    const compSize = buf.readUInt32LE(off + 20);
    const nameLen  = buf.readUInt16LE(off + 28);
    const extraLen = buf.readUInt16LE(off + 30);
    const cmtLen   = buf.readUInt16LE(off + 32);
    const localOff = buf.readUInt32LE(off + 42);
    const name     = buf.toString('utf8', off + 46, off + 46 + nameLen);
    if (name === wantedName) {
      const lNameLen  = buf.readUInt16LE(localOff + 26);
      const lExtraLen = buf.readUInt16LE(localOff + 28);
      const start = localOff + 30 + lNameLen + lExtraLen;
      const raw = buf.subarray(start, start + compSize);
      return method === 0 ? raw : zlib.inflateRawSync(raw);
    }
    off += 46 + nameLen + extraLen + cmtLen;
  }
  throw new Error(wantedName + ' niet gevonden in het document');
}

const unescapeXml = (s) => s
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&apos;/g, String.fromCharCode(39))
  .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)))
  .replace(/&amp;/g, '&');

function docxToText(buf) {
  const xml = zipRead(buf, 'word/document.xml').toString('utf8');
  const body = xml.replace(/<w:instrText[\s\S]*?<\/w:instrText>/g, '');
  const out = [];
  // tabellen eerst herkennen zodat rijen/cellen bewaard blijven
  const blocks = body.split(/(?=<w:tbl[ >])|(?<=<\/w:tbl>)/);
  for (const block of blocks) {
    if (block.startsWith('<w:tbl')) {
      for (const row of block.match(/<w:tr[ >][\s\S]*?<\/w:tr>/g) || []) {
        const cells = (row.match(/<w:tc[ >][\s\S]*?<\/w:tc>/g) || []).map(c =>
          unescapeXml((c.match(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g) || [])
            .map(t => t.replace(/<[^>]+>/g, '')).join('')).trim());
        if (cells.some(Boolean)) out.push('| ' + cells.join(' | ') + ' |');
      }
      out.push('');
      continue;
    }
    for (const para of block.match(/<w:p[ >][\s\S]*?<\/w:p>/g) || []) {
      const style = (para.match(/<w:pStyle w:val="([^"]+)"/) || [])[1] || '';
      let text = para
        .replace(/<w:tab\/>/g, '\t')
        .replace(/<w:br\s*\/>/g, '\n')
        .match(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g);
      text = unescapeXml((text || []).map(t => t.replace(/<[^>]+>/g, '')).join(''));
      if (!text.trim()) { out.push(''); continue; }
      const h = /^Heading(\d)/i.exec(style) || /^Kop(\d)/i.exec(style);
      out.push(h ? '#'.repeat(Math.min(Number(h[1]) + 1, 6)) + ' ' + text
                 : (/^Title$/i.test(style) ? '# ' + text : text));
    }
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}


function zipList(buf) {
  let eocd = -1;
  const floor = Math.max(0, buf.length - 65558);
  for (let i = buf.length - 22; i >= floor; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) return [];
  const count = buf.readUInt16LE(eocd + 10);
  let off = buf.readUInt32LE(eocd + 16);
  const names = [];
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(off) !== 0x02014b50) break;
    const nameLen = buf.readUInt16LE(off + 28);
    names.push(buf.toString('utf8', off + 46, off + 46 + nameLen));
    off += 46 + nameLen + buf.readUInt16LE(off + 30) + buf.readUInt16LE(off + 32);
  }
  return names;
}

const colIndex = (ref) => {
  const m = /^([A-Z]+)/.exec(ref || '');
  if (!m) return 0;
  return m[1].split('').reduce((a, c) => a * 26 + (c.charCodeAt(0) - 64), 0) - 1;
};

function xlsxToText(buf) {
  const shared = [];
  try {
    const ss = zipRead(buf, 'xl/sharedStrings.xml').toString('utf8');
    for (const si of ss.match(/<si>[\s\S]*?<\/si>/g) || [])
      shared.push(unescapeXml((si.match(/<t[^>]*>([\s\S]*?)<\/t>/g) || [])
        .map(t => t.replace(/<[^>]+>/g, '')).join('')));
  } catch (e) { /* geen gedeelde teksten */ }

  let names = {};
  try {
    const wbXml = zipRead(buf, 'xl/workbook.xml').toString('utf8');
    (wbXml.match(/<sheet[^>]*\/>/g) || []).forEach((s, i) => {
      const n = (s.match(/name="([^"]*)"/) || [])[1];
      names['sheet' + (i + 1) + '.xml'] = unescapeXml(n || ('Blad' + (i + 1)));
    });
  } catch (e) { /* namen niet beschikbaar */ }

  const sheets = zipList(buf)
    .filter(n => /^xl\/worksheets\/sheet\d+\.xml$/.test(n))
    .sort((a, b) => (+a.match(/(\d+)/)[1]) - (+b.match(/(\d+)/)[1]));

  const out = [];
  for (const path of sheets) {
    const short = path.split('/').pop();
    const xml = zipRead(buf, path).toString('utf8');
    const lines = [];
    for (const row of xml.match(/<row[ >][\s\S]*?<\/row>/g) || []) {
      const cells = [];
      for (const c of row.match(/<c[ >][\s\S]*?(?:<\/c>|\/>)/g) || []) {
        const type = (c.match(/ t="([^"]+)"/) || [])[1];
        const ref = (c.match(/ r="([^"]+)"/) || [])[1];
        let val = '';
        if (type === 'inlineStr') {
          val = unescapeXml((c.match(/<t[^>]*>([\s\S]*?)<\/t>/g) || [])
            .map(t => t.replace(/<[^>]+>/g, '')).join(''));
        } else {
          const v = (c.match(/<v>([\s\S]*?)<\/v>/) || [])[1];
          if (v != null) val = type === 's' ? (shared[Number(v)] ?? '') : unescapeXml(v);
        }
        cells[colIndex(ref)] = val;
      }
      for (let i = 0; i < cells.length; i++) if (cells[i] === undefined) cells[i] = '';
      if (cells.some(x => String(x).trim() !== '')) lines.push('| ' + cells.join(' | ') + ' |');
    }
    if (lines.length) out.push('## Werkblad: ' + (names[short] || short) + '\n' + lines.join('\n'));
  }
  return out.join('\n\n').trim();
}

const results = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const [key, meta] of Object.entries(bin)) {
    const name = meta.fileName || key;
    const buffer = await this.helpers.getBinaryDataBuffer(item.index ?? 0, key);
    let text = '', error = null;
    try {
      const lower = name.toLowerCase();
      if (lower.endsWith('.docx')) text = docxToText(buffer);
      else if (/\.(xlsx|xlsm)$/.test(lower)) text = xlsxToText(buffer);
      else if (lower.endsWith('.html') || lower.endsWith('.htm'))
        text = unescapeXml(buffer.toString('utf8')
          .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
          .replace(/<[^>]+>/g, ' ')).replace(/[ \t]{2,}/g, ' ').trim();
      else if (/\.(doc|xls|ppt)$/.test(lower))
        throw new Error('oud Office-formaat (' + lower.split('.').pop() + ') wordt niet ondersteund; sla op als docx, xlsx of pdf');
      else text = buffer.toString('utf8');
    } catch (e) { error = e.message; }
    if (text.length > MAX_CHARS_PER_DOC)
      text = text.slice(0, MAX_CHARS_PER_DOC) + '\n\n[...document afgekapt...]';
    results.push({ json: { bestandsnaam: name, tekens: text.length, tekst: text, fout: error } });
  }
}
return results;

// Bundelt alle geextraheerde documenttekst tot een blok voor de regisseur,
// en zet het oorspronkelijke chatbericht er weer bij.
const basis = $('Dossier samenstellen').first().json;

const MAX_TOTAAL = 120000;   // ruwweg 30k tokens; verhoog alleen als het model het aankan
const delen = [];
let nr = 0;

for (const item of $input.all()) {
  const j = item.json ?? {};
  nr++;
  const naam = j.bestandsnaam || item.binary?.data?.fileName || ('document ' + nr);
  if (j.fout) { delen.push(`--- ${naam} ---\n[KON NIET WORDEN GELEZEN: ${j.fout}]`); continue; }
  // 'tekst' komt uit de code-node, 'text' uit Extract From File (pdf)
  const tekst = String(j.tekst ?? j.text ?? '').trim();
  delen.push(tekst
    ? `--- ${naam} ---\n${tekst}`
    : `--- ${naam} ---\n[LEEG: geen tekst gevonden. Mogelijk een gescand document zonder tekstlaag.]`);
}

let context = delen.join('\n\n');
if (context.length > MAX_TOTAAL) {
  context = context.slice(0, MAX_TOTAAL) +
    '\n\n[...context afgekapt wegens omvang. Vraag de gebruiker om een kleiner document of om het relevante hoofdstuk.]';
}

return [{ json: { ...basis, documentContext: context, aantalDocumenten: delen.length } }];

