parameters.jsCode:
// Legt de RUWE specialistoutput van deze beurt vast. Dit is de kern van het dossier:
// zonder deze stap heeft een latere ronde (en de Rapportschrijver) alleen Jacky's
// samenvatting, niet de onderbouwing, rekenstappen en voorbehouden.
const agent = $('F&C regisseur').first().json ?? {};
const basis = $('Dossier samenstellen').first().json ?? {};

const MAX_INHOUD = 40000;   // per ronde; voorkomt dat een rij onbeperkt groeit

const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

const namen = [];
const delen = [];
for (const s of steps) {
  const naam = s?.action?.tool;
  if (!naam) continue;
  namen.push(naam);
  let obs = s.observation ?? '';
  if (typeof obs !== 'string') { try { obs = JSON.stringify(obs); } catch (e) { obs = String(obs); } }
  delen.push(`--- ${naam} ---\n${obs.trim()}`);
}

let inhoud = delen.join('\n\n');
if (inhoud.length > MAX_INHOUD) inhoud = inhoud.slice(0, MAX_INHOUD) + '\n[...afgekapt...]';

// Altijd precies EEN item terug, ook bij een intakebeurt zonder specialisten:
// de keten mag niet stilvallen, want het chatantwoord komt hierna pas.
return [{
  json: {
    session_id: basis.sessionId ?? $('When chat message received').first().json.sessionId ?? '',
    ronde: basis.volgendeRonde ?? 1,   // created_at zet Buddy Data er zelf bij
    specialisten: [...new Set(namen)].join(', '),
    vraag: String(basis.chatInput ?? '').slice(0, 2000),
    antwoord: String(agent.output ?? '').slice(0, 8000),
    inhoud,
  },
}];

// STILLE ORKESTRATIE
// De specialisten draaien onzichtbaar. De gebruiker ziet alleen Jacky's ene antwoord.
// Deze node staat NA het wegschrijven van het dossier, dus haalt de agentoutput direct op.
const DEBUG = true;

const agent = $('F&C regisseur').first().json ?? {};
const dossierRij = $('Specialistoutput uitpakken').first().json ?? {};

const messages = [{ agent: 'jacky', text: agent.output || '' }];
const out = { output: JSON.stringify(messages) };

if (DEBUG) {
  const tools = String(dossierRij.specialisten || '');
  const called = re => re.test(tools);
  out._debug_tools            = tools;
  out._debug_tool_count       = tools ? tools.split(',').length : 0;
  out._debug_fiscalist_called = called(/Fiscalist/i);   // moet bij elke adviesbeurt true zijn
  out._debug_accountant_called = called(/Accountant/i);
  out._debug_jurist_called    = called(/Jurist/i);
  out._debug_compliance_called = called(/Compliance/i);
  out._debug_notaris_called   = called(/Notaris/i);
  out._debug_governance_called = called(/governance/i);
  out._debug_data_called      = called(/Data/i);
  out._debug_rapport_called   = called(/Rapport/i);
  out._debug_ronde            = dossierRij.ronde;
  out._debug_dossier_rondes   = $('Dossier samenstellen').first().json.dossierRondes;
  out._debug_documenten       = $('Documentcontext bouwen').isExecuted
    ? $('Documentcontext bouwen').first().json.aantalDocumenten : 0;
}

return [{ json: out }];

